import { getMetaContent } from "helpers/meta_helpers"

const MILLISECONDS_PER_DAY = 1000 * 60 * 60 * 24

const timeFormatter = new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" })
const dateFormatterWithoutYear = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" })
const dateFormatterWithYear = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" })
const dayFormatter = new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" })
const dateTimeFormatter = new Intl.DateTimeFormat("en-US", {
  year: "2-digit", month: "numeric", day: "numeric", hour: "numeric", minute: "2-digit"
})

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_PER_DAY)
}

// Snap a timestamp to midnight in the viewer's browser timezone, so relative
// days ("yesterday", "in 3 days") match the viewer's calendar.
export function beginningOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

export function formatTime(date) {
  return timeFormatter.format(date)
}

export function formatDate(date, referenceDate = new Date()) {
  if (date.getFullYear() === referenceDate.getFullYear()) {
    return dateFormatterWithoutYear.format(date)
  } else {
    return dateFormatterWithYear.format(date)
  }
}

export function formatDay(date) {
  return dayFormatter.format(date)
}

export function formatDateTime(date) {
  return dateTimeFormatter.format(date)
}

// The server sends raw timestamps; the browser turns them into words in the
// viewer's timezone: "1:42 PM", "yesterday", "5 days ago", "Sep 12",
// "tomorrow" or "in 3 days".
export function formatRelativeTime(date, now = new Date()) {
  const differenceInDays = signedDifferenceInDays(now, date)

  switch (true) {
    case differenceInDays === 0:
      return date > now ? "today" : formatTime(date)
    case differenceInDays === -1:
      return "yesterday"
    case differenceInDays === 1:
      return "tomorrow"
    case differenceInDays < -1 && differenceInDays > -7:
      return `${-differenceInDays} days ago`
    case differenceInDays > 1:
      return `in ${differenceInDays} days`
    default:
      return formatDate(date, now)
  }
}

export function formatTimestamp(value, format = "relative", now = new Date()) {
  const date = parseDate(value)

  if (Number.isNaN(date.getTime())) return null

  switch (format) {
    case "time":
      return formatTime(date)
    case "date":
      return formatDate(date, now)
    case "day":
      return formatDay(date)
    case "datetime":
      return formatDateTime(date)
    default:
      return formatRelativeTime(date, now)
  }
}

export function formatTimestampWithZone(date) {
  const zone = Intl.DateTimeFormat().resolvedOptions().timeZone

  if (!zone) return null

  try {
    return new Intl.DateTimeFormat("en-US", {
      dateStyle: "long", timeStyle: "short", timeZone: zone
    }).format(date)
  } catch {
    return null
  }
}

// Date-only values (e.g. "2026-01-21") represent a calendar day for the viewer,
// so parse them in the browser's timezone instead of UTC.
function parseDate(value) {
  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    const [ year, month, day ] = value.split("-").map(Number)
    return new Date(year, month - 1, day)
  } else {
    return new Date(value)
  }
}
