import { formatTimestamp } from "helpers/date_helpers"

const SELECTOR = "time[datetime]"

function formatFor(element) {
  return element.dataset.localTimeFormat || element.dataset.localTime || "relative"
}

function render(element, now = new Date()) {
  const datetime = element.getAttribute("datetime")
  const formatted = formatTimestamp(datetime, formatFor(element), now)

  if (formatted && element.textContent !== formatted) {
    element.textContent = formatted
  }
}

function renderAll() {
  document.querySelectorAll(SELECTOR).forEach(element => render(element))
}

function renderAddedNodes(nodes) {
  nodes.forEach(node => {
    if (node.nodeType !== Node.ELEMENT_NODE) return

    if (node.matches(SELECTOR)) render(node)
    node.querySelectorAll(SELECTOR).forEach(element => render(element))
  })
}

function start() {
  renderAll()

  new MutationObserver(mutations => {
    mutations.forEach(mutation => {
      if (mutation.type === "attributes") {
        render(mutation.target)
      } else {
        renderAddedNodes(mutation.addedNodes)
      }
    })
  }).observe(document.documentElement, {
    subtree: true,
    childList: true,
    attributes: true,
    attributeFilter: [ "datetime" ]
  })

  setInterval(renderAll, 60 * 1000)
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", start, { once: true })
} else {
  start()
}
